import numpy as np
t=df['t'].values;A=df['A'].values;y=df['dA_dt'].values
L=np.log(A);s=np.sqrt(t)
tg=[np.ones_like(t),s,t]
def fit(extra):
    cols=[]
    base=[np.ones_like(A),A,A*L,A**2]
    for f in base+extra:
        for g in tg: cols.append(f*g)
    X=np.array(cols).T
    cc=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@cc)**2)/np.var(y)
